(()=>{'use strict';let pending=false;function fix(){pending=false;const root=document.querySelector('#main-content>.pati-saved-screen');if(root){root.style.top='0';root.style.transform='none';const back=root.querySelector('[data-saved-action="back"]');if(back){back.style.visibility='visible';back.style.opacity='1'}const header=root.querySelector('.pati-saved-page-header');if(header){header.style.visibility='visible';header.style.opacity='1'}}const actions=document.querySelector('#main-content .pati-ig-profile .pati-own-profile-actions');if(actions){const buttons=[...actions.querySelectorAll(':scope > button')];for(const b of buttons){if(/profili\s*düzenle/i.test(b.textContent||''))b.textContent=(b.textContent||'').replace(/profili\s*düzenle/i,'Düzenle')}}}function queue(){if(!pending){pending=true;requestAnimationFrame(fix)}}document.addEventListener('click',e=>{if(e.target.closest('.pati-saved-filter,[data-saved-action]')){requestAnimationFrame(queue);setTimeout(queue,100)}});new MutationObserver(queue).observe(document.getElementById('main-content')||document.documentElement,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',queue);queue()})();